INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'architect', 'n.', '/ˈɑːkɪtekt/', '建筑师;设计师', 'The architect was inspired by the shape of a lotus flower.', '这位建筑师从莲花的形状中获得了灵感。', 'Nature in Architecture', 1, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a famous architect', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'architecture', 'n.', '/ˈɑːkɪtektʃə/', '建筑设计;建筑风格', 'Nature has inspired many fascinating designs in architecture.', '大自然为建筑设计中许多迷人的作品带来了灵感。', 'Nature in Architecture', 2, 0, 'senior', 'wordlist', 'elective3', 'U5', 'modern architecture', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'lotus', 'n.', '/ˈləʊtəs/', '莲花;荷花', 'The museum was shaped to resemble a lotus floating on water.', '这座博物馆被设计成漂浮在水面上的莲花形状。', 'Nature in Architecture', 3, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a lotus flower', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'termite', 'n.', '/ˈtɜːmaɪt/', '白蚁', 'The architect watched how termites kept their nests cool.', '这位建筑师观察了白蚁如何让巢穴保持凉爽。', 'Nature in Architecture', 4, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a termite mound', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mound', 'n.', '/maʊnd/', '土堆;土丘', 'Holes in the mound allow air to move freely in and out.', '土丘上的小孔让空气自由进出。', 'Nature in Architecture', 5, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a termite mound', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'algae', 'n.', '/ˈældʒiː/', '藻类(植物)', 'The panels are full of algae that turn sunlight into energy.', '这些面板里满是把阳光转化为能量的藻类。', 'Nature in Architecture', 6, 0, 'senior', 'wordlist', 'elective3', 'U5', 'green algae', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tile', 'n.', '/taɪl/', '瓦片;瓷砖', 'A pine cone can look like the tiles on a roof.', '松果看起来很像屋顶上的瓦片。', 'Nature in Architecture', 7, 0, 'senior', 'wordlist', 'elective3', 'U5', 'roof tiles', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mimic', 'v.', '/ˈmɪmɪk/', '模仿;仿效', 'Architects often mimic the way nature solves problems.', '建筑师常常模仿大自然解决问题的方式。', 'Nature in Architecture', 8, 0, 'senior', 'wordlist', 'elective3', 'U5', 'mimic nature', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'biomimicry', 'n.', '/ˌbaɪəʊˈmɪmɪkri/', '仿生学', 'Biomimicry creates structures based on natural forms and processes.', '仿生学根据自然的形态和过程来创造结构。', 'Nature in Architecture', 9, 0, 'senior', 'wordlist', 'elective3', 'U5', 'an example of biomimicry', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'waterfront', 'n.', '/ˈwɔːtəfrʌnt/', '滨水地区;水边', 'The building seems to float above the waterfront.', '这座建筑仿佛漂浮在水边之上。', 'Nature in Architecture', 10, 0, 'senior', 'wordlist', 'elective3', 'U5', 'along the waterfront', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'promenade', 'n.', '/ˌprɒməˈnɑːd/', '滨海步行道', 'People walk along the promenade beside the water.', '人们沿着水边的步行道散步。', 'Nature in Architecture', 11, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a seaside promenade', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'plumbing', 'n.', '/ˈplʌmɪŋ/', '管道系统', 'Rainwater is recycled through the building''s plumbing system.', '雨水通过这座建筑的管道系统循环利用。', 'Nature in Architecture', 12, 0, 'senior', 'wordlist', 'elective3', 'U5', 'the building''s plumbing', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'superb', 'adj.', '/sjuːˈpɜːb/', '极好的;出色的', 'The Eastgate Centre is a superb example of biomimicry.', '东门中心是仿生学的一个出色范例。', 'Nature in Architecture', 13, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a superb example', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dioxide', 'n.', '/daɪˈɒksaɪd/', '二氧化物', 'The algae are fed with carbon dioxide to help them grow.', '藻类被喂以二氧化碳来帮助它们生长。', 'Nature in Architecture', 14, 0, 'senior', 'wordlist', 'elective3', 'U5', 'carbon dioxide', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'convert', 'v.', '/kənˈvɜːt/', '使转变;转化', 'The panels convert heat from the sun into energy.', '这些面板把太阳的热量转化为能量。', 'Nature in Architecture', 15, 0, 'senior', 'wordlist', 'elective3', 'U5', 'convert into', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'frontier', 'n.', '/ˈfrʌntɪə/', '(学科的)前沿;边界', 'Green buildings stand at the frontier of modern design.', '绿色建筑站在现代设计的前沿。', 'Nature in Architecture', 16, 0, 'senior', 'wordlist', 'elective3', 'U5', 'the frontier of design', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pond', 'n.', '/pɒnd/', '池塘', 'The garden has a quiet pond with fish swimming in it.', '园中有一方静静的池塘,鱼儿在里面游动。', 'Nature in Architecture', 17, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a garden pond', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sow', 'v.', '/səʊ/', '播(种)', 'Farmers learn from nature when to sow their crops.', '农民们向大自然学习何时播种庄稼。', 'Nature in Architecture', 18, 0, 'senior', 'wordlist', 'elective3', 'U5', 'sow seeds', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'wisdom', 'n.', '/ˈwɪzdəm/', '智慧;才智', 'Good design often comes from nature''s quiet wisdom.', '好的设计常常源于大自然无声的智慧。', 'Nature in Architecture', 19, 0, 'senior', 'wordlist', 'elective3', 'U5', 'nature''s wisdom', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'employ', 'v.', '/ɪmˈplɔɪ/', '使用;运用;雇用', 'Engineers now employ ideas borrowed from dolphins.', '工程师们如今运用从海豚身上借来的想法。', 'Nature in Architecture', 20, 0, 'senior', 'wordlist', 'elective3', 'U5', 'employ a method', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bat', 'n.', '/bæt/', '蝙蝠', 'Scientists study how a bat uses sound to find its way.', '科学家研究蝙蝠如何用声音辨别方向。', 'Nature in Architecture', 21, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a flying bat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'radar', 'n.', '/ˈreɪdɑː/', '雷达', 'The way bats hear sound helped improve radar systems.', '蝙蝠听声的方式帮助改进了雷达系统。', 'Nature in Architecture', 22, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a radar system', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dragonfly', 'n.', '/ˈdræɡənflaɪ/', '蜻蜓', 'By watching a dragonfly, designers built better small drones.', '通过观察蜻蜓,设计师造出了更好的小型无人机。', 'Nature in Architecture', 23, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a dragonfly in flight', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'drone', 'n.', '/drəʊn/', '无人驾驶飞机;无人机', 'The new drone copies the way a dragonfly moves.', '这架新无人机模仿了蜻蜓的运动方式。', 'Nature in Architecture', 24, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a small drone', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'spider', 'n.', '/ˈspaɪdə/', '蜘蛛', 'A spider makes silk that is stronger than steel of the same weight.', '蜘蛛吐出的丝比同等重量的钢还要结实。', 'Nature in Architecture', 25, 0, 'senior', 'wordlist', 'elective3', 'U5', 'spider silk', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'physician', 'n.', '/fɪˈzɪʃ(ə)n/', '医生;内科医生', 'Hua Tuo was a physician who learned much from nature.', '华佗是一位从大自然中学到很多的医生。', 'Nature in Architecture', 26, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a famous physician', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bow', 'v.', '/baʊ/', '鞠躬;低头', 'Tao refused to bow like a servant just for a little grain.', '陶渊明拒绝为了一点粮食像仆人一样低头。', 'Nature in Architecture', 27, 0, 'senior', 'wordlist', 'elective3', 'U5', 'bow to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'rural', 'adj.', '/ˈrʊərəl/', '农村的;乡村的', 'Tao spent his later years working the land in a rural area.', '陶渊明晚年在乡村耕作度日。', 'Nature in Architecture', 28, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a rural area', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cottage', 'n.', '/ˈkɒtɪdʒ/', '乡村小屋;村舍', 'Thoreau lived in a simple cottage by Walden Pond.', '梭罗住在瓦尔登湖边一间简朴的小屋里。', 'Nature in Architecture', 29, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a small cottage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'domestic', 'adj.', '/dəˈmestɪk/', '家养的;驯养的;家庭的', 'Tao wrote about domestic animals such as chickens and dogs.', '陶渊明写到鸡狗这类家养动物。', 'Nature in Architecture', 30, 0, 'senior', 'wordlist', 'elective3', 'U5', 'domestic animals', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'withdraw', 'v.', '/wɪðˈdrɔː/', '退出;离开', 'Both men were happy to withdraw from busy city life.', '两人都乐于从忙碌的城市生活中退出。', 'Nature in Architecture', 31, 0, 'senior', 'wordlist', 'elective3', 'U5', 'withdraw from', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'reluctant', 'adj.', '/rɪˈlʌktənt/', '不情愿的;勉强的', 'The smoke above the village seems reluctant to depart.', '村庄上方的炊烟仿佛不愿离去。', 'Nature in Architecture', 32, 0, 'senior', 'wordlist', 'elective3', 'U5', 'reluctant to leave', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'depart', 'v.', '/dɪˈpɑːt/', '离开;出发', 'The poet watched the evening clouds slowly depart.', '诗人望着傍晚的云彩缓缓离去。', 'Nature in Architecture', 33, 0, 'senior', 'wordlist', 'elective3', 'U5', 'depart from', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'lane', 'n.', '/leɪn/', '(乡间的)小路;巷', 'A dog is barking somewhere down the country lane.', '乡间小路深处有只狗在吠叫。', 'Nature in Architecture', 34, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a quiet lane', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'atop', 'prep.', '/əˈtɒp/', '在……顶上', 'Chickens sit atop the old mulberry tree at dusk.', '黄昏时,鸡群停在那棵老桑树顶上。', 'Nature in Architecture', 35, 0, 'senior', 'wordlist', 'elective3', 'U5', 'atop the tree', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mulberry', 'n.', '/ˈmʌlb(ə)ri/', '桑树;桑葚', 'An old mulberry tree stood beside the quiet cottage.', '一棵老桑树立在那间安静的小屋旁。', 'Nature in Architecture', 36, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a mulberry tree', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'purity', 'n.', '/ˈpjʊərɪti/', '纯洁;洁净', 'Thoreau wrote about the purity of the wild areas around him.', '梭罗描写了他周围荒野的纯净。', 'Nature in Architecture', 37, 0, 'senior', 'wordlist', 'elective3', 'U5', 'the purity of nature', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'resign', 'v.', '/rɪˈzaɪn/', '安于;使顺从;辞职', 'He told readers to resign themselves to the influence of each season.', '他告诉读者要顺应每个季节的影响。', 'Nature in Architecture', 38, 0, 'senior', 'wordlist', 'elective3', 'U5', 'resign yourself to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'botanical', 'adj.', '/bəˈtænɪk(ə)l/', '植物(学)的', 'We spent the morning in the city''s botanical garden.', '我们在城市的植物园里度过了一上午。', 'Nature in Architecture', 39, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a botanical garden', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'reject', 'v.', '/rɪˈdʒekt/', '拒绝接受;摒弃', 'It takes courage to reject the easy and familiar life.', '摒弃安逸熟悉的生活需要勇气。', 'Nature in Architecture', 40, 0, 'senior', 'wordlist', 'elective3', 'U5', 'reject the easy life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ease', 'n.', '/iːz/', '舒适;悠闲;自在', 'Both poets felt at ease with the quiet life in nature.', '两位诗人都对自然中的宁静生活感到自在。', 'Nature in Architecture', 41, 0, 'senior', 'wordlist', 'elective3', 'U5', 'at ease with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'attain', 'v.', '/əˈteɪn/', '得到;获得;实现', 'Living simply may help us attain a sense of well-being.', '简朴地生活也许能帮我们获得幸福感。', 'Nature in Architecture', 42, 0, 'senior', 'wordlist', 'elective3', 'U5', 'attain happiness', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fulfilment', 'n.', '/fʊlˈfɪlmənt/', '满足(感);成就感', 'A simple life close to nature can bring deep fulfilment.', '贴近自然的简单生活能带来深深的满足感。', 'Nature in Architecture', 43, 0, 'senior', 'wordlist', 'elective3', 'U5', 'personal fulfilment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'evaluate', 'v.', '/ɪˈvæljueɪt/', '评估;评价', 'Architects must evaluate how a design affects the environment.', '建筑师必须评估一项设计对环境的影响。', 'Nature in Architecture', 44, 0, 'senior', 'wordlist', 'elective3', 'U5', 'evaluate a design', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'deliberately', 'adv.', '/dɪˈlɪb(ə)rɪtli/', '从容不迫地;故意地', 'Thoreau went to the woods to live deliberately and simply.', '梭罗走进树林,只为从容而简朴地生活。', 'Nature in Architecture', 45, 0, 'senior', 'wordlist', 'elective3', 'U5', 'live deliberately', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'superficially', 'adv.', '/ˌsuːpəˈfɪʃ(ə)li/', '表面(上)地', 'Superficially, the two poets seem like polar opposites.', '表面上看,这两位诗人像是截然相反的人。', 'Nature in Architecture', 46, 0, 'senior', 'wordlist', 'elective3', 'U5', 'superficially different', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'decent', 'adj.', '/ˈdiːs(ə)nt/', '可接受的;相当好的;体面的', 'Thoreau had a decent life but chose a simpler one.', '梭罗本有体面的生活,却选择了更简单的方式。', 'Nature in Architecture', 47, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a decent life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'depressive', 'adj.', '/dɪˈpresɪv/', '压抑的;抑郁的', 'Tao''s calm country life stood in contrast to depressive court life.', '陶渊明宁静的乡村生活与压抑的官场生活形成对照。', 'Nature in Architecture', 48, 0, 'senior', 'wordlist', 'elective3', 'U5', 'depressive city life', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u5.01', '①doing / to do 作主语(及与谓语动词的单数一致)', 'A2', 12, '外研社版选择性必修第三册 U5 — 动名词(doing)或不定式(to do)可放在句首作主语,把动作名词化;作主语时谓语动词用单数(takes / is / requires)。', 1, 'elective3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u5.02', '②doing / to do 作宾语(动词搭配 + 介词后)', 'A2', 12, '外研社版选择性必修第三册 U5 — 及物动词后接动名词还是不定式由动词决定(enjoy doing / decide to do);介词后只能接动名词(be good at doing / by doing)。', 2, 'elective3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u5.03', '③doing / to do 作表语(系动词 be 之后)', 'A2', 12, '外研社版选择性必修第三册 U5 — 系动词 be 后的非谓语动词说明主语的内容或性质:His job is to design… / Her hobby is photographing…。', 3, 'elective3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ inspiration from nature is a tradition that goes back centuries.', 'Drawing', 'Draw', 'Draws', 'Drawn', 'A', '句首作主语要用名词化的动名词形式,Drawing inspiration… 表示"从自然中获取灵感"这件事。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ how a termite mound stays cool helped the architect design the centre.', 'Understand', 'Understanding', 'Understands', 'Understood', 'B', '主语位置需要动名词,Understanding… 把"理解"这一动作当作一件事。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ nature closely is the first step that every good designer takes.', 'Observe', 'Observes', 'Observing', 'Observed', 'C', '主语要用动名词 Observing nature,原形或过去分词都不能作主语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ buildings that breathe like living things is this architect''s dream.', 'Create', 'Creates', 'Created', 'Creating', 'D', '主语用动名词 Creating buildings…,谓语用单数 is。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ from the way nature works can solve many design problems.', 'Learning', 'Learn', 'Learns', 'Learned', 'A', '句首作主语需用动名词 Learning,表示"向自然学习"这件事。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ natural forms has become popular among modern architects.', 'Mimic', 'Mimicking', 'Mimics', 'Mimicked', 'B', '主语为动名词 Mimicking natural forms,谓语 has become 用单数。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ the environment matters as much as building beautiful homes.', 'Protect', 'Protects', 'Protecting', 'Protected', 'C', '主语用动名词 Protecting the environment,与后面的 building… 并列,都是名词化动作。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ copy the cooling system of a mound was the architect''s clever idea.', 'Will', 'Does', 'Has', 'To', 'D', '句首用不定式 To copy… 作主语,表示"去模仿"这件事;助动词不能引出主语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ live close to nature was the simple wish of both poets.', 'To', 'Is', 'Was', 'Did', 'A', '不定式 To live… 作主语,谓语是后面的 was;be/do 不能放在主语动词前。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ build in harmony with the land takes both art and science.', 'Build', 'To', 'Builds', 'Built', 'B', '不定式 To build… 作主语;原形或变化形式都不能单独作主语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ study how dolphins send signals led to better underwater systems.', 'Studies', 'Studied', 'To', 'Study', 'C', '不定式 To study… 作主语,把"研究"名词化。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ waste less energy is the main goal of these green buildings.', 'Wastes', 'Wasted', 'Waste', 'To', 'D', '不定式 To waste less energy 作主语,谓语为 is。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), '____ respect natural forms makes a building part of its surroundings.', 'To', 'Respects', 'Respected', 'Respect', 'A', '不定式 To respect… 作主语,谓语 makes 用单数。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), 'Designing such complex buildings ____ years of patient study.', 'take', 'takes', 'taking', 'to take', 'B', '动名词主语视为单数,谓语用 takes;非谓语形式不能作谓语。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), 'To copy the shape of a lotus flower ____ great skill.', 'require', 'requiring', 'requires', 'to require', 'C', '不定式主语用单数谓语 requires。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), 'Collecting rainwater through the roof ____ the building a lot of money.', 'save', 'saving', 'to save', 'saves', 'D', '动名词主语为单数,谓语用 saves。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), 'To live in harmony with the environment ____ careful planning.', 'needs', 'need', 'needing', 'to need', 'A', '不定式主语用单数谓语 needs。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), 'Capturing the beauty of natural forms ____ many young architects.', 'inspire', 'inspires', 'inspiring', 'to inspire', 'B', '动名词主语视为单数,谓语用 inspires。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), 'Watching termites build their nests ____ the engineer a brilliant idea.', 'give', 'giving', 'gives', 'to give', 'C', '动名词主语为单数,谓语用 gives。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.01'), 'To imitate a bird''s beak ____ engineers build quieter, faster trains.', 'help', 'helping', 'to help', 'helps', 'D', '不定式主语用单数谓语 helps。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'The architect enjoys ____ natural shapes into his designs.', 'bringing', 'bring', 'to bring', 'brought', 'A', 'enjoy 后接动名词作宾语,enjoy doing。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'They finished ____ the algae panels onto the wall last week.', 'fit', 'fitting', 'to fit', 'fitted', 'B', 'finish 后只能接动名词,finish doing。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'We should avoid ____ so much energy in our buildings.', 'waste', 'to waste', 'wasting', 'wasted', 'C', 'avoid 后接动名词作宾语,avoid doing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'The designer kept ____ the way termites cool their mounds.', 'study', 'to study', 'studied', 'studying', 'D', 'keep doing 表示"不断做",宾语用动名词。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'Have you considered ____ rainwater for the garden?', 'collecting', 'collect', 'to collect', 'collected', 'A', 'consider 后接动名词作宾语,consider doing。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'The class practised ____ small models of green houses.', 'make', 'making', 'to make', 'made', 'B', 'practise 后接动名词作宾语,practise doing。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'Imagine ____ in a house whose walls are covered with living plants.', 'live', 'to live', 'living', 'lived', 'C', 'imagine 后接动名词作宾语,imagine doing。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'The young architect decided ____ the museum like a lotus flower.', 'shaping', 'shape', 'shaped', 'to shape', 'D', 'decide 后接不定式作宾语,decide to do。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'Mick Pearce wanted ____ a building that needed no air conditioning.', 'to create', 'creating', 'create', 'created', 'A', 'want 后接不定式作宾语,want to do。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'Engineers hope ____ from nature to solve human problems.', 'learning', 'to learn', 'learn', 'learned', 'B', 'hope 后接不定式作宾语,hope to do。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'The city agreed ____ the old garden in its original style.', 'restoring', 'restore', 'to restore', 'restored', 'C', 'agree 后接不定式作宾语,agree to do。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'She chose ____ in a quiet cottage far from the noisy city.', 'living', 'live', 'lived', 'to live', 'D', 'choose 后接不定式作宾语,choose to do。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'They planned ____ the building''s energy use by half.', 'to cut', 'cutting', 'cuts', 'having cut', 'A', 'plan 后接不定式作宾语,plan to do。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'The team managed ____ the algae alive through the cold winter.', 'keeping', 'to keep', 'keep', 'kept', 'B', 'manage 后接不定式作宾语,manage to do。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'The students are interested in ____ how nature really works.', 'study', 'to study', 'studying', 'studied', 'C', '介词 in 后只能接动名词,be interested in doing。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'By ____ a shark''s skin, scientists created faster swimsuits.', 'copy', 'to copy', 'copied', 'copying', 'D', '介词 by 后接动名词,by doing 表方式。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'The architect is good at ____ ideas from the natural world.', 'borrowing', 'borrow', 'to borrow', 'borrowed', 'A', '介词 at 后只能接动名词,be good at doing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'Instead of ____ traditional heating, the building uses natural warm air.', 'use', 'using', 'to use', 'used', 'B', '介词短语 instead of 后接动名词,instead of doing。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'We look forward to ____ the new nature-inspired library next month.', 'visit', 'be visited', 'visiting', 'visited', 'C', 'look forward to 中的 to 是介词,后接动名词,visit 应改为 visiting。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.02'), 'After ____ the documentary about termites, he had a new idea.', 'watch', 'to watch', 'watched', 'watching', 'D', '介词 after 后接动名词,after doing。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The architect''s goal is ____ a building that lives with nature.', 'to design', 'design', 'designs', 'designed', 'A', 'be 后用不定式作表语,说明 goal 的具体内容。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'Mick Pearce''s idea was ____ the cooling system of termite mounds.', 'copy', 'to copy', 'copies', 'copied', 'B', 'be 后用不定式作表语,was to copy 说明 idea 的内容。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The main aim of the design is ____ less energy than normal buildings.', 'use', 'uses', 'to use', 'used', 'C', 'is 后用不定式作表语,说明 aim 是什么。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'Her dream is ____ houses whose walls are full of green plants.', 'build', 'builds', 'built', 'to build', 'D', 'be 后用不定式作表语,说明 dream 的内容。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The first step is ____ how natural forms actually work.', 'to understand', 'understand', 'understands', 'understood', 'A', 'is 后用不定式作表语,the first step is to do。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The plan is ____ rainwater and reuse it inside the building.', 'collect', 'to collect', 'collects', 'collected', 'B', 'be 后用不定式作表语,说明 plan 的内容。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'Our task today is ____ which design best suits the hot climate.', 'decide', 'decides', 'to decide', 'decided', 'C', 'is 后用不定式作表语,说明 task 是什么。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The architect''s wish is ____ in closer harmony with the environment.', 'live', 'lives', 'lived', 'to live', 'D', 'be 后用不定式作表语,说明 wish 的内容。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The point of biomimicry is ____ nature''s clever solutions.', 'to borrow', 'borrow', 'borrows', 'borrowed', 'A', 'is 后用不定式作表语,说明 the point 是什么。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The next goal is ____ the building''s beauty without harming nature.', 'keep', 'to keep', 'keeps', 'kept', 'B', 'is 后用不定式作表语,说明 goal 的内容。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The best part of his job is ____ ideas from plants and animals.', 'borrow', 'borrows', 'borrowing', 'borrowed', 'C', 'be 后用动名词作表语,说明"工作中最好的部分"是哪件事。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'Her hobby is ____ old buildings that copy natural shapes.', 'photograph', 'photographs', 'photographed', 'photographing', 'D', 'be 后用动名词作表语,her hobby is doing。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'One way to save energy is ____ on natural light during the day.', 'relying', 'rely', 'relies', 'relied', 'A', 'be 后用动名词作表语,说明"省电的一种方式"。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'His favourite activity is ____ wild plants in the botanical garden.', 'draw', 'drawing', 'draws', 'drew', 'B', 'be 后用动名词作表语,说明"最喜欢的活动"是什么。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'A big part of green design is ____ less water and power.', 'use', 'uses', 'using', 'used', 'C', 'be 后用动名词作表语,说明"绿色设计的一大部分"。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The hardest job was ____ the algae alive in winter.', 'keep', 'keeps', 'kept', 'keeping', 'D', 'be 后用动名词作表语,说明"最难的工作"是哪件事。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'One pleasure of country life is ____ to the birds each morning.', 'listening', 'listen', 'listens', 'listened', 'A', 'be 后用动名词作表语,说明"乡村生活的一种乐趣"。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'Their main business is ____ gardens that copy wild nature.', 'build', 'building', 'builds', 'built', 'B', 'be 后用动名词作表语,说明 business 是哪件事。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The real challenge is ____ comfort and nature at the same time.', 'balance', 'balances', 'balancing', 'balanced', 'C', 'be 后用动名词作表语,说明"真正的挑战"是哪件事。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U5' AND code='fe3u5.03'), 'The best way to cool the rooms is ____ plants on the roof.', 'grow', 'grows', 'grew', 'growing', 'D', 'be 后用动名词作表语,说明"最好的办法"是哪件事。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Building Like a Lotus', 'Singapore''s ArtScience Museum was built to show how nature and a busy modern city can sit happily together. From above, the white building looks like a giant lotus flower resting on the water beside the crowded promenade. Ten finger-like parts reach up into the sky, and each one lets daylight pour down into the rooms below. The most surprising feature, however, is hidden in the roof. When it rains, the curved roof gathers the water and sends it thirty-five metres straight down to a small waterfall in the heart of the building. The water is then cleaned and used once more through the building''s pipes, so almost nothing is lost. People who step inside are often amazed to find such a calm, watery world right in the middle of a noisy city. The architect hoped that visitors would feel how a modern building can still capture the quiet beauty of natural forms.', '说明·新加坡艺术科学博物馆', 152, '[{"q":"Why was the ArtScience Museum built in this special shape?","answer":"A","options":["To show that nature and a modern city can fit together.","To make the building the tallest one in the city.","To copy an old palace from ancient times.","To hide the museum from busy crowds."],"explanation":"首句说博物馆是为了表现自然与现代城市能和谐共处,选项是其转述。"},{"q":"What happens to the rainwater that falls on the roof?","answer":"B","options":["It is thrown straight into the sea.","It is cleaned and used again inside the building.","It is sold to nearby shops.","It is left to dry on the roof."],"explanation":"原文说雨水被净化后通过管道再次使用,选项是其概括。"},{"q":"How do visitors usually feel inside the museum?","answer":"A","options":["Surprised to find a quiet, watery space in a busy city.","Bored because the rooms are all empty.","Frightened by the loud city noise inside.","Tired of climbing the ten tall towers."],"explanation":"原文说人们惊讶于在喧闹城市中竟有如此平静的水世界,选项是转述。"}]'::jsonb, '[{"word":"promenade","cn":"滨海步行道"},{"word":"waterfront","cn":"滨水地区"}]'::jsonb, 2, 'elective3', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Cool Like a Termite Mound', 'The Eastgate Centre in Harare is one of the world''s best-known green buildings, and its secret comes from insects. While watching a nature programme, the architect Mick Pearce saw termites building tall mounds full of tiny holes. These holes let air move in and out, keeping the inside cool even when the African sun is burning. Pearce gave his building the same kind of skin. During the hot day, warm air is pulled in through small openings and cools down as it travels towards the centre of the building. At night, heat stored in the thick walls gently warms the cool night air, so the rooms stay comfortable around the clock. Because of this clever design, the Centre needs almost no ordinary air conditioning or heating. It uses far less power than buildings of a similar size, and it costs much less money to run each year. Nature, it seems, had already solved the problem long before.', '说明·哈拉雷东门中心(仿生学)', 157, '[{"q":"Where did Mick Pearce get the idea for his building?","answer":"B","options":["From an old book about modern cities.","From watching how termites build their mounds.","From a dream he had one night.","From a museum of ancient art."],"explanation":"原文说他看自然节目时受到白蚁筑巢的启发,选项是其概括。"},{"q":"How do the rooms stay comfortable during the night?","answer":"C","options":["Powerful heaters run all night long.","The windows are kept tightly shut.","Heat held by the thick walls during the day warms the night.","Warm water is pumped through the floor."],"explanation":"原文说夜里墙体储存的热量温暖了凉空气,选项是转述。"},{"q":"What is the main benefit of this design?","answer":"D","options":["It makes the building look much taller.","It keeps insects out of the rooms.","It allows the building to move with the wind.","It saves a great deal of energy and money."],"explanation":"原文强调建筑用电少、运行成本低,选项是其概括。"}]'::jsonb, '[{"word":"termite","cn":"白蚁"},{"word":"mound","cn":"土堆;土丘"}]'::jsonb, 2, 'elective3', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Home Powered by Plants', 'In Hamburg, Germany, stands the world''s first building powered by tiny water plants. The flat sides of this apartment block are covered with glass panels, and inside each panel lives a green liquid full of algae. The algae are fed with carbon dioxide and simple nutrients so that they keep growing. On bright sunny days they grow quickly and spread across the panels, giving the rooms cool shade. At the same time, the panels trap heat from the sun and turn it into electricity for the building. The story does not end there. When the algae have grown enough, they can be collected and made into fuel. In this way the building does three jobs at once: it shades its rooms, it makes its own clean power, and it even helps the environment by using up waste gas. Many architects now travel to Hamburg to study how living plants can become a real part of a modern home.', '说明·汉堡藻类公寓', 158, '[{"q":"What makes this Hamburg building unusual?","answer":"A","options":["It gets its power from living algae in glass panels.","It is built completely under the ground.","It has no windows of any kind.","It floats on a large lake."],"explanation":"原文说这是世界上首座靠水生植物供能的建筑,选项是其概括。"},{"q":"What do the algae do on bright sunny days?","answer":"B","options":["They die quickly and must be replaced.","They grow fast and provide shade while energy is made.","They turn brown and stop working.","They are removed from the panels."],"explanation":"原文说晴天藻类快速生长、提供遮阴,同时面板发电,选项是转述。"},{"q":"Why do many architects travel to Hamburg?","answer":"C","options":["To buy cheap apartments by the river.","To watch a famous sports match.","To learn how living plants can be built into homes.","To paint pictures of the old town."],"explanation":"原文说建筑师前往研究活体植物如何融入现代住宅,选项是其概括。"}]'::jsonb, '[{"word":"algae","cn":"藻类(植物)"},{"word":"convert","cn":"转化"}]'::jsonb, 2, 'elective3', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Answers from the Wild', 'Looking to nature for answers is an old idea with a modern name: biomimicry. It means studying the shapes and habits of living things and then borrowing their best ideas. Long ago, the Wright brothers watched birds gliding through the air before they built their first flying machine. Today the same way of thinking shapes our trains. Engineers noticed that a kingfisher''s long beak lets the bird dive into water without a splash, so they gave high-speed trains a similar pointed nose. The change made the trains both faster and much quieter. Animals have also taught us to send messages under the sea. After studying how dolphins call to one another in deep water, scientists built warning systems that tell coastal towns when a huge wave is coming. Each of these inventions began not in a laboratory but out in the wild. When we meet a hard problem today, nature has often tested the answer for millions of years already.', '说明·仿生学综述', 160, '[{"q":"What does the word biomimicry mean in this text?","answer":"D","options":["Building machines only inside laboratories.","Keeping wild animals away from cities.","Painting pictures of plants and animals.","Borrowing the clever designs found in living things."],"explanation":"原文解释 biomimicry 是研究并借用生物的优良设计,选项是其概括。"},{"q":"Why were high-speed trains given a pointed nose?","answer":"A","options":["To run faster and more quietly, like a diving bird.","To carry far more passengers than before.","To look like an old steam engine.","To stop more easily at stations."],"explanation":"原文说模仿翠鸟的喙让列车更快更安静,选项是转述。"},{"q":"How did studying dolphins help people?","answer":"B","options":["It taught people how to swim faster.","It led to systems that warn towns about big waves.","It helped farmers grow more crops.","It made ships much larger."],"explanation":"原文说研究海豚的交流方式催生了海啸预警系统,选项是其概括。"}]'::jsonb, '[{"word":"biomimicry","cn":"仿生学"},{"word":"employ","cn":"运用"}]'::jsonb, 2, 'elective3', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Two Poets, One Love', 'Tao Yuanming and Henry David Thoreau lived almost fifteen hundred years and half a world apart, yet they shared one deep love: nature. Tao was an official in ancient China, but he felt trapped by life at court. In the end he gave up his post and spent his remaining years farming in a poor country village. His daily life was hard, but his poems show that he found real peace among the fields, chickens and trees. Thoreau, an American writer, was not forced to leave society; instead he chose to. For two years he lived alone in a small cottage beside Walden Pond, watching the seasons change and writing about all he saw. He believed that animals and plants have the same right to live well as people do. Both men gave up comfort and fame for a quieter, simpler way of living, and both were sure that staying close to nature could make a person feel whole.', '记叙·陶渊明与梭罗归隐', 159, '[{"q":"Why did Tao Yuanming give up his official post?","answer":"C","options":["He was sent away by the emperor.","He wanted to become a rich merchant.","He was unhappy and no longer wished to serve at court.","He was too ill to keep working."],"explanation":"原文说陶渊明对官场生活感到困顿不快,选项是转述。"},{"q":"How was Thoreau''s move to nature different from Tao''s?","answer":"D","options":["Thoreau was forced to leave his home.","Thoreau moved into a busy city.","Thoreau travelled with a large group.","Thoreau left ordinary society by his own free choice."],"explanation":"原文说梭罗不是被迫,而是自己选择离开,选项是其概括。"},{"q":"What did both poets believe about nature?","answer":"A","options":["A simple life close to nature can make a person whole.","Nature is dangerous and should be avoided.","City life is always better than country life.","Only rich people can enjoy nature."],"explanation":"原文末句说二人都相信亲近自然能让人完整,选项是转述。"}]'::jsonb, '[{"word":"rural","cn":"乡村的"},{"word":"withdraw","cn":"退出"}]'::jsonb, 2, 'elective3', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Mountains in a Garden', 'Chinese classical gardens were designed to bring the wild world inside the city wall. The Lingering Garden in Suzhou is a famous example of this gentle art. Its builders did not simply plant a few trees; they tried to recreate whole mountains, rivers and forests in miniature. A pile of strange rocks stands for a tall mountain, a small pool becomes a wide lake, and a single twisted pine suggests an ancient forest. Visitors are meant to explore the garden slowly, scene by scene, just as they might wander through real countryside. Around every corner a new view appears: a moon-shaped gate, a tree in blossom, or fish splashing in a quiet pond. Nothing is shown all at once, because surprise is an important part of the design. Walking here, a busy city dweller can forget the noise outside and feel, for a short while, that the whole of nature has been folded gently into one small and peaceful space.', '说明·苏州园林', 160, '[{"q":"What did the builders of the Lingering Garden try to do?","answer":"B","options":["Build the largest palace in the country.","Recreate wild nature in miniature inside the city.","Grow food for the whole town.","Copy a famous garden in another land."],"explanation":"原文说造园者试图把山川森林缩小再现,选项是其概括。"},{"q":"In the garden, what does a pile of strange rocks stand for?","answer":"C","options":["A busy market.","A deep well.","A tall mountain.","A city gate."],"explanation":"原文明确说乱石堆象征高山,选项是其转述。"},{"q":"Why are the views revealed only a little at a time?","answer":"D","options":["Because the garden is too dark to see far.","Because visitors are not allowed to walk far.","Because the plants block every path.","Because surprise is meant to be part of the design."],"explanation":"原文说不一次展现全部,因为惊喜是设计的一部分,选项是转述。"}]'::jsonb, '[{"word":"pond","cn":"池塘"},{"word":"wisdom","cn":"智慧"}]'::jsonb, 2, 'elective3', 'U5', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U5', 'The Green Tower', 'Last summer my class visited a tall green (1)____ in the city centre. From far away it looked like a giant tree made of glass and steel. Our guide told us that the (2)____ had studied real forests before drawing his plans. Living plants grew on every floor, so the air inside felt fresh and (3)____. The walls were covered with small panels that could (4)____ sunlight into clean electricity. I was (5)____ to learn that the building used almost no power from outside. On the roof there was a quiet (6)____ where birds came to drink. Our guide said that good design should (7)____ from nature instead of fighting against it. At the end of the visit, each of us tried to (8)____ a simple model of a green house. Mine was far from perfect, but making it helped me (9)____ how hard an architect''s job really is. I left the tower feeling that nature and the city could live in (10)____ after all.', 165, 2, '[{"q":"1","answer":"A","options":["tower","garden","river","song"],"explanation":"a tall green tower 与下文 the tower 呼应。"},{"q":"2","answer":"B","options":["farmer","architect","driver","singer"],"explanation":"drawing his plans 说明是建筑师。"},{"q":"3","answer":"C","options":["loud","dark","clean","heavy"],"explanation":"fresh and clean 搭配,描述空气。"},{"q":"4","answer":"D","options":["throw","buy","hide","turn"],"explanation":"turn sunlight into electricity 把阳光转化为电。"},{"q":"5","answer":"A","options":["surprised","angry","bored","afraid"],"explanation":"得知建筑几乎不用外来电力,作者感到惊讶。"},{"q":"6","answer":"B","options":["road","pond","wall","door"],"explanation":"鸟来喝水的地方是池塘。"},{"q":"7","answer":"C","options":["hide","escape","learn","fall"],"explanation":"learn from nature 向自然学习。"},{"q":"8","answer":"D","options":["eat","sell","lose","build"],"explanation":"build a model 制作模型。"},{"q":"9","answer":"A","options":["understand","forget","doubt","refuse"],"explanation":"helped me understand 帮我理解。"},{"q":"10","answer":"B","options":["danger","harmony","silence","anger"],"explanation":"live in harmony 和谐共处。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U5', 'A Roof Like a Leaf', 'An engineer once spent a whole month watching how a large (1)____ collected rain and let it run off gently. She noticed that its surface was not flat but slightly (2)____, so the water never stayed too long. This simple idea gave her a clever (3)____ for a new kind of roof. Working with a small team, she began to (4)____ a roof that copied the shape of the leaf. The team had to (5)____ many models before they found one that worked. Their goal was to (6)____ rainwater and send it down into a tank below. When heavy rain came, the new roof stayed dry and (7)____, just like the leaf. People who saw it were (8)____ by how natural it looked. The engineer later said that nature had been her best (9)____ all along. Now several schools have asked her to (10)____ the same kind of roof for them.', 151, 2, '[{"q":"1","answer":"C","options":["stone","box","leaf","clock"],"explanation":"下文 like the leaf 指明是叶子。"},{"q":"2","answer":"D","options":["dry","dark","loud","curved"],"explanation":"slightly curved 表面略微弯曲,使水不停留。"},{"q":"3","answer":"A","options":["idea","price","noise","meal"],"explanation":"a clever idea 一个聪明的想法。"},{"q":"4","answer":"B","options":["eat","design","buy","sell"],"explanation":"design a roof 设计屋顶。"},{"q":"5","answer":"C","options":["hide","lose","test","throw"],"explanation":"test many models 测试很多模型。"},{"q":"6","answer":"D","options":["waste","burn","spill","collect"],"explanation":"collect rainwater 收集雨水。"},{"q":"7","answer":"A","options":["strong","wet","cold","soft"],"explanation":"stayed dry and strong 又干又结实。"},{"q":"8","answer":"B","options":["bored","amazed","angry","tired"],"explanation":"amazed by 对其自然外观感到惊叹。"},{"q":"9","answer":"C","options":["problem","enemy","teacher","secret"],"explanation":"nature had been her best teacher 自然是她最好的老师。"},{"q":"10","answer":"D","options":["break","spoil","paint","build"],"explanation":"build the same roof 为学校建造同样的屋顶。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U5', 'The School That Breathes', 'Our new school looks quite different from any other in the town. Its walls are covered with green (1)____ that grow all year round. In summer, the leaves give cool (2)____, so the classrooms never become too hot. In winter, sunlight passes through the bare branches and (3)____ the rooms naturally. The architect who designed it wanted us to (4)____ in harmony with nature every day. Instead of using a lot of (5)____, the building makes much of its own from the sun. Rain that falls on the roof is not (6)____; it is stored and used to water the plants. Even the air feels (7)____ because so many leaves clean it. Some visitors find it hard to (8)____ that a school can work this way. But our teachers say the design has helped us (9)____ that people and plants belong together. Studying here has changed the way I (10)____ about the future of our cities.', 156, 2, '[{"q":"1","answer":"A","options":["plants","stones","signs","wires"],"explanation":"green plants 绿色植物,与 leaves/branches 呼应。"},{"q":"2","answer":"B","options":["noise","shade","smoke","dust"],"explanation":"cool shade 凉爽的树荫。"},{"q":"3","answer":"C","options":["cools","floods","warms","breaks"],"explanation":"冬日阳光自然地温暖房间。"},{"q":"4","answer":"D","options":["fight","hide","sleep","live"],"explanation":"live in harmony with nature 与自然和谐相处。"},{"q":"5","answer":"A","options":["power","salt","paper","glass"],"explanation":"下文 makes much of its own from the sun 指电力/能源。"},{"q":"6","answer":"B","options":["planted","wasted","opened","frozen"],"explanation":"雨水没有被浪费,而是被储存使用。"},{"q":"7","answer":"C","options":["heavy","dirty","fresh","warm"],"explanation":"叶子净化空气,空气清新。"},{"q":"8","answer":"D","options":["sell","count","paint","believe"],"explanation":"hard to believe 难以相信。"},{"q":"9","answer":"A","options":["see","forget","doubt","deny"],"explanation":"helped us see that 帮我们认识到。"},{"q":"10","answer":"B","options":["walk","think","eat","run"],"explanation":"the way I think about the future 我对未来的看法。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U5', 'Lessons from a Bird''s Nest', 'A young designer named Lin loved to watch birds build their (1)____ in the trees near her home. She was amazed by how strong and light they were, even though birds use only grass and (2)____. One spring she decided to (3)____ how the tiny builders worked. For weeks she sat quietly and made careful (4)____ of every step. She learned that a good nest must (5)____ both wind and rain without breaking. This wild wisdom gave her the (6)____ to design a new kind of light roof for camps. Her first model was too weak, so she had to (7)____ it again and again. In the end her design proved both cheap and (8)____. Lin often says that the birds were her real (9)____. Thanks to them, she now helps families build homes that can (10)____ strong winds far better than before.', 143, 2, '[{"q":"1","answer":"C","options":["roads","shops","nests","boats"],"explanation":"birds build their nests 鸟筑巢。"},{"q":"2","answer":"D","options":["gold","paint","glass","mud"],"explanation":"grass and mud 草和泥,鸟筑巢的材料。"},{"q":"3","answer":"A","options":["study","sell","hide","win"],"explanation":"study how the builders worked 研究小工匠如何工作。"},{"q":"4","answer":"B","options":["jokes","notes","meals","calls"],"explanation":"made careful notes 做了仔细的记录。"},{"q":"5","answer":"C","options":["sell","paint","face","lose"],"explanation":"face both wind and rain 经受风雨。"},{"q":"6","answer":"D","options":["fear","price","noise","idea"],"explanation":"the idea to design 设计的灵感/想法。"},{"q":"7","answer":"A","options":["test","throw","buy","lose"],"explanation":"test it again and again 一次次测试。"},{"q":"8","answer":"B","options":["wet","strong","dark","slow"],"explanation":"cheap and strong 又便宜又结实。"},{"q":"9","answer":"C","options":["problems","enemies","teachers","prizes"],"explanation":"the birds were her real teachers 鸟是她真正的老师。"},{"q":"10","answer":"D","options":["enjoy","paint","sell","resist"],"explanation":"homes that can resist strong winds 能抵御大风的房屋。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U5', 'A Little Garden at Home', 'Last year my grandmother taught me to grow vegetables in our small (1)____ behind the house. At first I had no idea how to (2)____ the seeds, so she showed me where each one should go. She told me that a good gardener must learn to (3)____ and never rush nature. Some mornings I felt (4)____ because nothing seemed to be growing at all. But slowly, tiny green leaves began to (5)____ through the dark soil. Grandmother said that watching them was her favourite (6)____ of the day. We gave the plants water, sunlight and plenty of (7)____. By the end of summer our garden was full of (8)____ vegetables. I was proud that my own hands had (9)____ them. From that little garden I learned that good things take time, and that patience can (10)____ a real reward.', 139, 2, '[{"q":"1","answer":"A","options":["garden","kitchen","office","river"],"explanation":"grow vegetables in our small garden 在小菜园里种菜。"},{"q":"2","answer":"B","options":["eat","plant","sell","paint"],"explanation":"plant the seeds 播种。"},{"q":"3","answer":"C","options":["shout","hide","wait","run"],"explanation":"learn to wait 学会等待,不催促自然。"},{"q":"4","answer":"D","options":["proud","glad","brave","worried"],"explanation":"什么都没长,作者感到担心。"},{"q":"5","answer":"A","options":["push","fall","sleep","fly"],"explanation":"leaves began to push through the soil 嫩芽顶出泥土。"},{"q":"6","answer":"B","options":["price","part","noise","meal"],"explanation":"her favourite part of the day 一天中最喜欢的时刻。"},{"q":"7","answer":"C","options":["salt","smoke","care","dust"],"explanation":"plenty of care 充足的照料。"},{"q":"8","answer":"D","options":["broken","dirty","dead","fresh"],"explanation":"fresh vegetables 新鲜的蔬菜。"},{"q":"9","answer":"A","options":["grown","lost","sold","burnt"],"explanation":"my own hands had grown them 亲手种出。"},{"q":"10","answer":"B","options":["break","bring","hide","cost"],"explanation":"patience can bring a reward 耐心能带来回报。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U5', 'A Weekend in the Country', 'Last weekend I stayed in a small (1)____ deep in the countryside, far from the noisy town. There was no traffic, only the soft (2)____ of birds in the morning. The owner, an old farmer, lived there in great (3)____, with a garden, a few chickens and an old dog. He told me that he had once worked in a big city but had chosen to (4)____ from that busy life. Every evening he liked to (5)____ on the doorstep and watch the sun go down behind the hills. At first the deep silence made me feel a little (6)____, but soon I began to enjoy it. The fresh air and slow days helped me (7)____ all my worries. I understood why so many writers have loved this kind of (8)____ life. On Sunday I was almost (9)____ to leave such a peaceful place. The short stay taught me that quietness can be a real (10)____.', 156, 2, '[{"q":"1","answer":"C","options":["factory","station","cottage","library"],"explanation":"a small cottage 乡间小屋。"},{"q":"2","answer":"D","options":["smell","taste","weight","songs"],"explanation":"the soft songs of birds 鸟儿轻柔的歌声。"},{"q":"3","answer":"A","options":["ease","danger","hurry","fear"],"explanation":"lived there in great ease 过着十分悠闲的生活。"},{"q":"4","answer":"B","options":["copy","withdraw","build","sell"],"explanation":"withdraw from that busy life 退出忙碌的生活。"},{"q":"5","answer":"C","options":["cook","drive","sit","shout"],"explanation":"sit on the doorstep 坐在门口台阶上。"},{"q":"6","answer":"D","options":["proud","hungry","brave","lonely"],"explanation":"深深的寂静起初让人有点孤独。"},{"q":"7","answer":"A","options":["forget","count","sell","paint"],"explanation":"helped me forget all my worries 帮我忘却烦恼。"},{"q":"8","answer":"B","options":["busy","simple","modern","crowded"],"explanation":"this kind of simple life 这种简单的生活。"},{"q":"9","answer":"C","options":["glad","proud","sorry","eager"],"explanation":"almost sorry to leave 几乎舍不得离开。"},{"q":"10","answer":"D","options":["problem","noise","crime","gift"],"explanation":"quietness can be a real gift 宁静是一份真正的礼物。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·对话 At the Green Building Show', '外研社版选择性必修第三册 U5 · dialogue', 3, 'Lucy: Hi Tom, how was the exhibition of green buildings yesterday?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·独白 The Wonder of Spider Silk', '外研社版选择性必修第三册 U5 · passage', 2, 'Welcome to today''s science minute. Spider silk is one of nature''s most surprising materials. Although it is very thin and light, it is far stronger than steel of the same weight. Scientists would love to use it to make safer clothing and lighter ropes. The problem is that spiders are hard to keep in large numbers, so there is still not enough silk. Researchers are now trying to copy spider silk in the laboratory. If they succeed, this gift from a tiny animal could change the way we build and travel.', '今天的科学一分钟介绍蜘蛛丝:它是自然界最神奇的材料之一,虽然又细又轻,却比同等重量的钢还结实;科学家想用它做更安全的衣物和更轻的绳索,但蜘蛛难以大量饲养,丝还不够;研究人员正尝试在实验室里仿制蜘蛛丝,若成功,这份来自小动物的礼物或将改变我们建造与出行的方式。', 'uk_female', '[{"q":"What is the talk mainly about?","type":"choice","answer":"D","options":["How to keep spiders as pets.","The history of cloth making.","Different kinds of steel.","Spider silk and how it might be used."]},{"q":"How strong is spider silk?","type":"choice","answer":"A","options":["Stronger than steel of the same weight.","Weaker than thin paper.","About the same as cotton.","Heavier than iron."]},{"q":"Why is there still not enough spider silk?","type":"choice","answer":"B","options":["The silk dries out too quickly.","Spiders are hard to keep in large numbers.","It is forbidden to collect it.","Nobody wants to use it."]},{"q":"What are researchers trying to do now?","type":"choice","answer":"C","options":["Train spiders to spin faster.","Sell silk to other countries.","Copy spider silk in the laboratory.","Stop using silk completely."]},{"q":"What could spider silk be used to make?","type":"choice","answer":"D","options":["Heavier cars and trucks.","Loud musical instruments.","Stronger glass windows.","Safer clothing and lighter ropes."]}]'::jsonb, '[]'::jsonb, 'short', 'elective3', 'U5', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·对话 Interview with a Young Architect', '外研社版选择性必修第三册 U5 · dialogue', 3, 'Host: Today we welcome Mei, a young architect who designs nature-friendly buildings. Welcome, Mei.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·独白 The Train and the Bird', '外研社版选择性必修第三册 U5 · passage', 2, 'Have you ever wondered why some fast trains have such a long, pointed nose? The answer comes from a small bird called the kingfisher. When a kingfisher dives into water to catch a fish, its sharp beak hardly makes a splash. Engineers in Japan noticed this and gave their trains a similar shape. The new design let the trains run faster and, just as importantly, much more quietly. So the next time you see a high-speed train rush by, remember that its clever shape was a gift from a little bird.', '你是否好奇为何有些高速列车有又长又尖的车头?答案来自一种叫翠鸟的小鸟:翠鸟扎入水中捕鱼时,尖喙几乎不溅起水花;日本工程师注意到这点,给列车设计了类似的形状;新设计让列车跑得更快、也安静得多;所以下次看到高速列车飞驰而过,记住它聪明的外形是一只小鸟的馈赠。', 'uk_female', '[{"q":"What is the talk about?","type":"choice","answer":"B","options":["How birds build their nests.","Why some fast trains have a pointed nose.","Where to catch fish in rivers.","How to drive a train safely."]},{"q":"What can a kingfisher do well?","type":"choice","answer":"C","options":["Fly higher than any other bird.","Sing in the early morning.","Dive into water without much splash.","Swim under the ice."]},{"q":"Where did engineers use the kingfisher''s shape?","type":"choice","answer":"D","options":["On large ships.","On tall buildings.","On small cars.","On high-speed trains."]},{"q":"What were the two results of the new design?","type":"choice","answer":"A","options":["The trains became faster and quieter.","The trains became slower and heavier.","The trains became larger and louder.","The trains became cheaper and shorter."]},{"q":"Where does the speaker say the idea came from?","type":"choice","answer":"B","options":["From an old book.","From a little bird.","From a busy city.","From a science class."]}]'::jsonb, '[]'::jsonb, 'short', 'elective3', 'U5', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·对话 A Roof Garden for Our School', '外研社版选择性必修第三册 U5 · dialogue', 3, 'Anna: Mr Lee, our class wants to build a small garden on the school roof. Can we?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·独白 Wisdom of the Solar Terms', '外研社版选择性必修第三册 U5 · passage', 2, 'Long ago in ancient China, farmers watched the sky and the land very carefully. By noticing small changes in the sun, the weather and the plants, they created the 24 Solar Terms. Each term told them the best time to sow seeds or to bring in the harvest. This simple calendar, drawn from nature''s own signs, guided farmers for hundreds of years. Today the 24 Solar Terms are still remembered, and in 2016 they were added to a famous list of the world''s cultural heritage. They remind us how much wisdom people can gain by listening to nature.', '很久以前的古代中国,农民仔细观察天空与土地;通过留意太阳、天气和植物的细微变化,他们创立了二十四节气;每个节气告诉他们何时播种、何时收割;这份取自自然征兆的简单历法指引农民数百年;如今二十四节气仍被铭记,并于2016年被列入世界文化遗产名录;它提醒我们,倾听自然能让人获得多少智慧。', 'uk_female', '[{"q":"What did ancient Chinese farmers watch carefully?","type":"choice","answer":"D","options":["The busy markets.","The city walls.","The royal court.","The sky and the land."]},{"q":"What did the 24 Solar Terms tell farmers?","type":"choice","answer":"A","options":["The best time to sow or harvest.","The price of grain.","The way to a new city.","The names of the stars."]},{"q":"Where did this calendar come from?","type":"choice","answer":"B","options":["From a foreign country.","From nature''s own signs.","From an old machine.","From a king''s order."]},{"q":"What happened to the 24 Solar Terms in 2016?","type":"choice","answer":"C","options":["They were first written down.","They were used by farmers for the first time.","They were added to a cultural heritage list.","They were forgotten by everyone."]},{"q":"What is the main lesson of the talk?","type":"choice","answer":"D","options":["Old calendars are no longer useful.","Farming is easy work.","Cities are better than the countryside.","People gain wisdom by listening to nature."]}]'::jsonb, '[]'::jsonb, 'short', 'elective3', 'U5', 'fltrp');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Introduce a Nature-Inspired Building(介绍一座向自然学习的建筑)', 'A Building That Learns from Nature', '你校英文报正在征集"建筑中的自然"主题短文。请用英语写一篇约100词的介绍,内容包括:① 这座建筑从哪种自然事物获得灵感;② 它如何运作(如收集雨水、节省能源等);③ 为什么它对环境有益。要求恰当使用本单元的非谓语结构(如 Designing such buildings takes…/Her goal is to copy…/The aim is using less energy)。', 'Your school''s English newspaper is collecting short articles on the theme ''Nature in Architecture''. Write a passage of about 100 words to introduce a nature-inspired building, including: 1) what natural thing gave the designer the idea; 2) how the building works (for example, collecting rainwater or saving energy); 3) why it is good for the environment. Try to use the non-finite structures from this unit (doing / to do as subject, object and predicative).', '["灵感来源(The idea came from… / Watching … inspired the architect)","运作方式(Collecting rainwater saves… / Its job is to turn sunlight into energy)","环境益处(Using less energy helps protect…)","恰当运用非谓语作主语/宾语/表语,句子地道连贯"]'::jsonb, 70, 100, 'Copying nature is one of the cleverest things an architect can do, and the Eastgate Centre in Harare proves it. The idea came from watching how termites keep their tall mounds cool. Mick Pearce''s goal was to build something that needed no ordinary air conditioning. Designing such a building took years, but the result is superb. During the day the walls draw in warm air; at night they slowly release the stored heat. Using far less energy than normal buildings, the Centre also costs less to run. To learn from nature, it seems, is to design for the future.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Copying nature is one of the cleverest things an architect can do.","Mick Pearce''s goal was to build something that needed no ordinary air conditioning.","Designing such a building took years, but the result is superb.","To learn from nature, it seems, is to design for the future."]'::jsonb, '[{"wrong":"Design such a building took years.","correct":"Designing such a building took years.","note":"作主语要用动名词或不定式,不能用动词原形。"},{"wrong":"His goal was build a cool house.","correct":"His goal was to build a cool house.","note":"be 后作表语用不定式 to do。"},{"wrong":"The idea came from watch the termites.","correct":"The idea came from watching the termites.","note":"介词 from 后接动名词。"}]'::jsonb, '【介绍一座向自然学习的建筑】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective3', 'U5', '{"title":"非谓语动词作主语 / 宾语 / 表语(to do · doing)速查","intro":"一个句子只能有一个谓语;其它动作要变成非谓语(to do 或 doing)。本单元三种用法:放句首作主语、放动词或介词后作宾语、放系动词 be 后作表语。判断口诀:句首作主语→谓语用单数;介词后→一律用 doing;动词后→看这个动词\"吃\"哪一种。","table":{"headers":["成分","形式 / 例句"],"rows":[["主语(句首)","动名词或不定式:Designing such buildings takes years. / To copy nature requires skill.(谓语用单数)"],["宾语·动词后","由动词决定:enjoy/finish/avoid/keep + doing;want/decide/hope/agree + to do"],["宾语·介词后","一律 doing:be good at copying / by watching / instead of using / look forward to seeing"],["表语(be 后)","His job is to design… / Her hobby is photographing… / Seeing is believing."]]},"specialRules":[{"rule":"动名词/不定式作主语,谓语动词用单数","mark":"Collecting rainwater saves money.(saves 不用 save)"},{"rule":"介词后只能用动名词,不用不定式","mark":"be interested in studying √ / in to study ×"},{"rule":"look forward to / be used to 里的 to 是介词,后接 doing","mark":"look forward to visiting √"},{"rule":"want/decide/hope/agree/manage/plan 后接不定式;enjoy/finish/avoid/keep/practise/consider 后接动名词","mark":"decide to do √ / enjoy doing √"}],"why":["非谓语就是把一个动作\"名词化\":作主语 = 谁/什么事;作宾语 = 对什么；作表语 = 主语\"是\"什么事。一旦动作不再充当句子的谓语,就必须换成 to do 或 doing。"],"gaokaoPoints":["语法填空 / 短文改错高频:句首给动词原形要变 doing 或 to do;介词后给原形要变 doing。","主谓一致陷阱:动名词主语后谓语用单数(Designing… takes…)。","辨析:同一动词后 doing 与 to do 意义不同的(remember/forget/stop/try)本单元不强求,先掌握固定搭配。"],"examVsReal":[{"exam":"To copy nature requires skill.（考试/书面更正式）","real":"Copying nature takes skill.","note":"考试两种皆可;口语里动名词作主语更自然常见。"},{"exam":"His job is to design green buildings.（不定式作表语)","real":"His job is designing green buildings.","note":"说明\"一直在做的事\"时,口语常用 doing 作表语,语感更强调\"经常性\"。"}]}'::jsonb, 'fltrp');
